public class Calculo {
    static int processar(int v) {
        try {
            if (v < 0) {
                throw new IllegalArgumentException();
            }
            return v * 2;
        } catch (IllegalArgumentException e) {
            return -1;
        } finally {
            v = v + 100;
        }
    }

    public static void main(String[] args) {
        System.out.print(processar(5) + " " + processar(-3));
    }
}

